 {
  "id": "U01",
  "name": "김민수",
  "amount": 10000
 },
 {
  "id": "U02",
  "name": "김민수",
  "amount": 20000
 },
 {
  "id": "U03",
  "name": "이지은",
  "amount": 5000
 }
]
실행 결과: name_key_rows: [
 {
  "id": "U02",
  "name": "김민수",
  "amount": 20000
 },
 {
  "id": "U03",
